import {JOINT_MIN,displayLandmarks} from './pose-quality.mjs';
import {drawBones,artworkReady} from './bone-overlay.mjs';
import {poseAt} from './pose-playback.mjs';
const SAMPLE_RATE=30;
const $=id=>document.getElementById(id),video=$('video'),canvas=$('canvas'),ctx=canvas.getContext('2d');
let model,PoseLandmarker,url,frames=[],busy=false,cancel=false,filename='',lastFrame=null;
const edges=[[11,12],[11,13],[13,15],[12,14],[14,16],[11,23],[12,24],[23,24],[23,25],[25,27],[24,26],[26,28],[27,29],[29,31],[27,31],[28,30],[30,32],[28,32],[0,7],[0,8]];
const maskCanvas=document.createElement('canvas'),mc=maskCanvas.getContext('2d');
const clock=t=>`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;
function status(s){$('status').textContent=s}
function angle(p,a,b,c){if(![a,b,c].every(i=>p[i]?.visibility>=JOINT_MIN))return null;let u=[(p[a].x-p[b].x)*canvas.width,(p[a].y-p[b].y)*canvas.height],v=[(p[c].x-p[b].x)*canvas.width,(p[c].y-p[b].y)*canvas.height];let d=Math.hypot(...u)*Math.hypot(...v);return d?Math.acos(Math.max(-1,Math.min(1,(u[0]*v[0]+u[1]*v[1])/d)))*180/Math.PI:null}
function metrics(p){if(!p)return {left:null,right:null,tilt:null,confidence:null};let good=[11,12,23,24].every(i=>p[i].visibility>=JOINT_MIN);return {left:angle(p,23,25,27),right:angle(p,24,26,28),tilt:good?Math.atan2(Math.abs((p[11].x+p[12].x-p[23].x-p[24].x)*canvas.width),Math.abs((p[23].y+p[24].y-p[11].y-p[12].y)*canvas.height))*180/Math.PI:null,confidence:p.reduce((a,b)=>a+b.visibility,0)/p.length*100}}
function draw(){if(!video.videoWidth)return;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(video,0,0,canvas.width,canvas.height);let f=poseAt(frames,video.currentTime,SAMPLE_RATE);lastFrame=f;if(f?.mask&&$('silhouette').checked){maskCanvas.width=f.mw;maskCanvas.height=f.mh;const im=mc.createImageData(f.mw,f.mh);for(let i=0;i<f.mask.length;i++){im.data[i*4]=160;im.data[i*4+1]=218;im.data[i*4+2]=123;im.data[i*4+3]=f.mask[i]>.5*255?90:0}mc.putImageData(im,0,0);ctx.drawImage(maskCanvas,0,0,canvas.width,canvas.height)}if(f?.p&&$('skeleton').checked&&$('overlayStyle').value==='bones'){drawBones(ctx,f.p,canvas.width,canvas.height,Number($('boneOpacity').value),$('jointDots').checked)}if(f?.p&&$('skeleton').checked&&$('overlayStyle').value==='landmarks'){ctx.strokeStyle='#ccff9a';ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=Math.max(2,canvas.width/350);for(const [a,b]of edges){if(f.p[a].visibility<JOINT_MIN||f.p[b].visibility<JOINT_MIN)continue;ctx.beginPath();ctx.moveTo(f.p[a].x*canvas.width,f.p[a].y*canvas.height);ctx.lineTo(f.p[b].x*canvas.width,f.p[b].y*canvas.height);ctx.strokeStyle='#102319';ctx.lineWidth=Math.max(6,canvas.width/150);ctx.stroke();ctx.strokeStyle='#caff43';ctx.lineWidth=Math.max(3,canvas.width/280);ctx.stroke()}for(const p of f.p){if(p.visibility<JOINT_MIN)continue;ctx.beginPath();ctx.arc(p.x*canvas.width,p.y*canvas.height,Math.max(3,canvas.width/250),0,Math.PI*2);ctx.fillStyle='#f6ffb8';ctx.fill();ctx.strokeStyle='#102319';ctx.lineWidth=1.5;ctx.stroke()}}let m=f?.p?metrics(f.p):{};for(const k of ['left','right','tilt','confidence'])$(k).textContent=m[k]==null?'—':Math.round(m[k])+(k==='confidence'?'%':'°');$('skeletonHint').textContent=!$('skeleton').checked?'Skeleton hidden':!frames.length?(busy?'Detecting body posture…':'Turn on the skeleton to start detection'):!f?'This part of the video has not been analyzed':!f.p?'No person detected in this frame — try a clear full-body view':f.p.filter(p=>p.visibility>=JOINT_MIN).length<2?'Pose confidence too low to draw the skeleton':'Skeleton tracking detected posture';$('seek').value=video.currentTime;$('time').textContent=`${clock(video.currentTime)} / ${clock(video.duration||0)}`;}
function tick(){if(!busy)draw();requestAnimationFrame(tick)}requestAnimationFrame(tick);
function seek(t){return new Promise((resolve,reject)=>{if(Math.abs(video.currentTime-t)<.00001&&video.readyState>=2)return resolve();let timer=setTimeout(()=>{cleanup();reject(new Error('Video frame could not be decoded. Try another MP4 or WebM.'))},10000);function cleanup(){clearTimeout(timer);video.removeEventListener('seeked',done)}function done(){cleanup();resolve()}video.addEventListener('seeked',done);video.currentTime=t})}
async function load(file){if(!file||busy)return;if(!file.type.startsWith('video/')){status('Please select a video file.');return}video.pause();frames=[];$('json').disabled=true;$('snapshot').disabled=true;$('analyze').disabled=true;$('play').disabled=true;$('seek').disabled=true;if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(file);filename=file.name;$('filename').textContent=filename;video.src=url;status('Opening video…');$('badge').textContent='LOADING VIDEO';$('progress').value=0;}
video.addEventListener('loadeddata',()=>{if(!Number.isFinite(video.duration)||video.duration<=0){status('This video has no usable duration. Try an MP4 file.');return}if(video.duration>120){status('Please choose a clip up to 2 minutes long.');$('badge').textContent='CLIP TOO LONG';return}canvas.width=Math.min(1280,video.videoWidth);canvas.height=Math.round(canvas.width*video.videoHeight/video.videoWidth);$('empty').hidden=true;$('stage').style.aspectRatio=`${canvas.width}/${canvas.height}`;$('seek').max=video.duration;$('seek').disabled=false;$('play').disabled=false;$('analyze').disabled=false;$('badge').textContent='VIDEO LOADED';status('Video ready. Turn on the skeleton or select Analyze walking video.');draw();if($('skeleton').checked&&!busy&&!frames.length)$('analyze').click()});
video.addEventListener('error',()=>{status('This video format could not be decoded. Try H.264 MP4 or WebM.');$('badge').textContent='VIDEO ERROR'});
$('choose').onclick=$('replace').onclick=()=>$('file').click();$('file').onchange=e=>{load(e.target.files[0]);e.target.value=''};
$('stage').ondragover=e=>e.preventDefault();$('stage').ondrop=e=>{e.preventDefault();load(e.dataTransfer.files[0])};
$('play').onclick=async()=>{if(video.paused){try{await video.play()}catch(e){status('Playback could not start: '+e.message)}}else video.pause()};video.onplay=()=>{$('play').textContent='Ⅱ'};video.onpause=()=>{$('play').textContent='▶'};$('seek').oninput=e=>{video.currentTime=Number(e.target.value)};$('speed').onchange=e=>video.playbackRate=Number(e.target.value);
async function init(){await artworkReady;if(model){model.close();model=null;}status('Loading high-detail pose model…');const mp=await import('./vendor/vision_bundle.mjs');PoseLandmarker=mp.PoseLandmarker;const vision=await mp.FilesetResolver.forVisionTasks('./vendor/wasm');model=await PoseLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:'./vendor/pose_landmarker_heavy.task',delegate:'CPU'},runningMode:'VIDEO',numPoses:1,outputSegmentationMasks:true,minPoseDetectionConfidence:.5,minPosePresenceConfidence:.5,minTrackingConfidence:.65})}
$('analyze').onclick=async()=>{if(busy){cancel=true;return}busy=true;cancel=false;video.pause();frames=[];$('json').disabled=$('snapshot').disabled=true;$('play').disabled=$('seek').disabled=$('replace').disabled=true;$('file').disabled=true;$('analyze').textContent='Stop analysis';$('badge').textContent='ANALYZING';try{await init();let total=Math.ceil(video.duration*SAMPLE_RATE);for(let i=0;i<total;i++){if(cancel)break;let t=Math.min(i/SAMPLE_RATE,video.duration-.001);await seek(t);let frame={t,p:null,raw:null,world:null,metrics:{}};model.detectForVideo(video,t*1000,r=>{frame.raw=r.landmarks[0]?.map(p=>({...p}))||null;frame.p=displayLandmarks(frame.raw);frame.world=r.worldLandmarks[0]?.map(p=>({...p}))||null;frame.metrics=metrics(frame.p);const m=r.segmentationMasks?.[0];if(m){const raw=m.getAsFloat32Array();frame.mw=128;frame.mh=Math.max(1,Math.round(128*m.height/m.width));frame.mask=new Uint8Array(frame.mw*frame.mh);for(let y=0;y<frame.mh;y++)for(let x=0;x<frame.mw;x++)frame.mask[y*frame.mw+x]=Math.round(raw[Math.floor(y*m.height/frame.mh)*m.width+Math.floor(x*m.width/frame.mw)]*255)}});frames.push(frame);$('progress').value=(i+1)/total*100;status(`Analyzing frame ${i+1} of ${total} · ${clock(t)}`);draw();await new Promise(r=>setTimeout(r,0))}let detected=frames.filter(f=>f.p).length;$('badge').textContent=cancel?'PARTIAL ANALYSIS':'ANALYSIS COMPLETE';status(`${cancel?'Stopped. ':''}${detected} of ${frames.length} sampled frames contain a pose. ${detected?'Scrub the timeline to inspect results.':'Try a clearer full-body video.'}`);await seek(0);draw()}catch(e){console.error(e);status('Analysis failed: '+e.message+'. Try reopening Mia in Chrome or Edge.');$('badge').textContent='ANALYSIS ERROR'}finally{busy=false;$('analyze').innerHTML='Analyze walking video <span>↗</span>';$('play').disabled=$('seek').disabled=$('replace').disabled=$('file').disabled=false;$('json').disabled=!frames.length;$('snapshot').disabled=!frames.length}};
function download(blob,name){let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
$('json').onclick=()=>download(new Blob([JSON.stringify({video:filename,model:"pose_landmarker_heavy",sampleRate:SAMPLE_RATE,jointVisibilityThreshold:JOINT_MIN,complete:$('badge').textContent==='ANALYSIS COMPLETE',description:'Single person. Normalized image landmarks and model-estimated world landmarks. Angles are 2D degrees. Silhouette is visible segmentation, not body dimensions.',frames:frames.map(({t,p,raw,world,metrics})=>({timeSeconds:t,landmarks:p,rawLandmarks:raw,worldLandmarks:world,metrics}))},null,2)],{type:'application/json'}),'mia-landmarks.json');
$('snapshot').onclick=()=>{draw();canvas.toBlob(b=>{if(b)download(b,`mia-frame-${video.currentTime.toFixed(2)}.png`)},'image/png')};


function syncSkeleton(startDetection=false){const enabled=$('skeleton').checked;$('skeletonButton').setAttribute('aria-pressed',String(enabled));$('skeletonButton').textContent=enabled?'Skeleton: ON':'Skeleton: OFF';draw();if(startDetection&&enabled&&!busy&&!frames.length&&video.readyState>=2&&!$('analyze').disabled)$('analyze').click();if(enabled&&!video.videoWidth)$('skeletonHint').textContent='Choose a video — detection will start automatically'}
$('skeletonButton').onclick=()=>{$('skeleton').checked=!$('skeleton').checked;syncSkeleton(true)};$('skeleton').onchange=()=>syncSkeleton(true);syncSkeleton();

$('overlayStyle').onchange=draw;$('boneOpacity').oninput=()=>{$('opacityValue').textContent=Math.round(Number($('boneOpacity').value)*100)+'%';draw()};$('jointDots').onchange=draw;
